from elftools.elf.elffile import ELFFile

# Try to get line info for these addresses
with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    dwarfinfo = elf.get_dwarf_info()
    for addr in [0x2f4b20, 0x2f4c84]:
        found = False
        for CU in dwarfinfo.iter_CUs():
            lp = dwarfinfo.line_program_for_CU(CU)
            if lp is None:
                continue
            prev_state = None
            for entry in lp.get_entries():
                if entry.state is None:
                    continue
                if prev_state and prev_state.address <= addr < entry.state.address:
                    fname = lp['file_entry'][prev_state.file - 1].name.decode()
                    print(f'0x{addr:x} -> {fname}:{prev_state.line}')
                    found = True
                    break
                prev_state = entry.state
            if found:
                break
        if not found:
            print(f'0x{addr:x} -> not found in line tables')
" 2>&1", "description": "Check line tables for addresses", "initial_wait": 120}
